package com.nigson.commerce.order;
import java.util.*;
import java.time.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;
import com.nigson.commerce.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.*;
public final class OrderService implements OrderCheckout {
 private final OrderRepository repository;private final OrderAuthority authority;private final CheckoutPayments payments;private final PlatformStore commands;private final AuditWriter audit;private final JdbcTemplate jdbc;private final TransactionTemplate reads;private final Clock clock;private final io.micrometer.core.instrument.MeterRegistry metrics;
 public OrderService(OrderRepository repository,OrderAuthority authority,CheckoutPayments payments,PlatformStore commands,AuditWriter audit,JdbcTemplate jdbc,PlatformTransactionManager manager,Clock clock,io.micrometer.core.instrument.MeterRegistry metrics){this.repository=repository;this.authority=authority;this.payments=payments;this.commands=commands;this.audit=audit;this.jdbc=jdbc;this.clock=clock;this.metrics=metrics;reads=new TransactionTemplate(manager);reads.setReadOnly(true);reads.setTimeout(2);reads.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);}
 private void limits(){jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");}
 private PlatformStore.Response execute(ActorAssertion.Actor actor,String api,String key,Object body,UUID correlation,boolean staff,java.util.function.Supplier<PlatformStore.Response> change){ApiValues.idempotencyKey(key);if(correlation==null)throw ApiValues.invalid();ApiValues.uuid(correlation.toString());try{return commands.executeLocal(actor.party().toString(),api,key,EventCodec.JSON.valueToTree(body),db->{limits();if(staff)authority.staff(actor,true,true);else authority.customer(actor,true);return change.get();});}catch(org.springframework.dao.DataAccessException failure){for(Throwable cause=failure;cause!=null;cause=cause.getCause())if(cause instanceof java.sql.SQLException sql&&Set.of("55P03","57014").contains(sql.getSQLState()))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_IN_PROGRESS);throw failure;}}
 private void evidence(ActorAssertion.Actor actor,AuditValues.Action action,OrderValues.Order order,Long before,UUID correlation,String operation){audit.append(actor.party().toString(),AuditValues.ActorKind.USER,action,AuditValues.Resource.ORDER,order.id(),correlation,AuditValues.Reason.OPERATOR_REQUEST,before==null?null:Map.of("version",before),Map.of("version",order.version(),"state",order.status()),null);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.order.commands","operation",operation).increment();}});}
 private void event(ActorAssertion.Actor actor,OrderValues.Order order,String type,UUID correlation){Instant now=clock.instant();var value=new LinkedHashMap<String,Object>();value.put("event_id",EventCodec.uuid7(now));value.put("event_type",type);value.put("schema_version",1);value.put("producer","commerce");value.put("occurred_at",now);value.put("aggregate_id",order.id());value.put("aggregate_version",order.version());value.put("organization_id",repository.organization(order.id()));value.put("correlation_id",correlation);value.put("traceparent",null);Map<String,Object> payload;if(type.equals("order.pending.v1")){String market=jdbc.queryForObject("SELECT m.code FROM commerce.sales_order o JOIN commerce.market m ON m.id=o.market_id WHERE o.id=?",String.class,order.id());payload=Map.of("order_id",order.id(),"party_id",actor.party(),"market_code",market);}else if(type.equals("order.cancelled.v1"))payload=Map.of("order_id",order.id(),"reason_code","CUSTOMER_REQUEST");else payload=Map.of("order_id",order.id());value.put("payload",payload);commands.append(EventCodec.JSON.writeValueAsString(value),actor.party().toString());}
 public OrderValues.Checkout pending(ActorAssertion.Actor actor,OrderValues.CheckoutInput input,UUID correlation){if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("LOCAL_TRANSACTION_REQUIRED");limits();authority.customer(actor,true);repository.quoteOwner(actor,input.checkoutQuoteId());payments.requireReady();if(correlation==null)throw ApiValues.invalid();ApiValues.uuid(correlation.toString());var created=repository.checkout(actor,input,correlation);var result=created.checkout();if(created.created()){evidence(actor,AuditValues.Action.ORDER_CHECKOUT,result.order(),null,correlation,"CHECKOUT");event(actor,result.order(),"order.pending.v1",correlation);}return result;}
 public OrderValues.Checkout checkout(ActorAssertion.Actor actor,OrderValues.CheckoutInput input,String key,UUID correlation){authority.customer(actor,false);repository.quoteOwner(actor,input.checkoutQuoteId());payments.requireReady();var response=execute(actor,"API-037",key,input,correlation,false,()->{repository.quoteOwner(actor,input.checkoutQuoteId());var result=pending(actor,input,correlation);return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(result),result.order().id());});var result=EventCodec.JSON.treeToValue(response.body(),OrderValues.Checkout.class);authority.owned(actor,result.order().id(),false);payments.initialize(result.order().id(),correlation);return reads.execute(status->{limits();authority.owned(actor,result.order().id(),false);return new OrderValues.Checkout(repository.find(result.order().id(),false),repository.payment(result.order().id()));});}
 public OrderValues.Order get(ActorAssertion.Actor actor,UUID order){authority.owned(actor,order,false);return reads.execute(status->{limits();authority.owned(actor,order,false);return repository.find(order,false);});}
 public OrderValues.Page list(ActorAssertion.Actor actor,OrderValues.Query query,boolean staff){if(staff)authority.staff(actor,false,false);else{authority.customer(actor,false);authority.organization(actor,query.organizationId(),false);}return reads.execute(status->{limits();if(staff)authority.staff(actor,false,false);else{authority.customer(actor,false);authority.organization(actor,query.organizationId(),false);}return repository.list(actor,query,staff);});}
 public OrderValues.Order processing(ActorAssertion.Actor actor,UUID order,long version,String reason,String key,UUID correlation){authority.staff(actor,true,false);repository.find(order,false);var response=execute(actor,"API-044",key,Map.of("id",order,"version",version,"reason",reason),correlation,true,()->{var after=repository.processing(order,version,actor.party().toString(),reason);evidence(actor,AuditValues.Action.ORDER_PROCESSING,after,version,correlation,"PROCESS");event(actor,after,"order.processing.v1",correlation);return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(after),order);});return EventCodec.JSON.treeToValue(response.body(),OrderValues.Order.class);}
 public OrderValues.Order cancelled(ActorAssertion.Actor actor,UUID order,long version,String reason,String key,UUID correlation){authority.owned(actor,order,false);ApiValues.idempotencyKey(key);if(correlation==null)throw ApiValues.invalid();if(!commands.completed(actor.party().toString(),"API-040",key))payments.inspect(order,correlation);var response=execute(actor,"API-040",key,Map.of("id",order,"version",version,"reason",reason),correlation,false,()->{authority.owned(actor,order,true);var after=repository.cancelled(order,version,actor.party().toString(),reason,correlation);evidence(actor,AuditValues.Action.ORDER_CANCELLATION,after,version,correlation,"CANCEL");event(actor,after,"order.cancelled.v1",correlation);return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(after),order);});return EventCodec.JSON.treeToValue(response.body(),OrderValues.Order.class);}
 public OrderValues.Proof proof(PrivateWorkload.Proof proof,OrderValues.ProofInput input){if(proof==null||!proof.client().equals("nigson-experience")||proof.subject()==null||proof.subject().isBlank()||proof.actor()!=null||!proof.route().api().equals("API-121")||!proof.route().owner().equals("commerce")||!proof.route().client().equals("nigson-experience")||!proof.route().scope().equals("purchase-proof.read"))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return reads.execute(status->{limits();return repository.proof(input);});}
}
